'use strict';
(()=>{
let generation=0,network=null,delayTimer=null,wake=null,lastTrack=null,lastOptions={},allowLossy=false;const sourceIds=new Map();try{allowLossy=localStorage.getItem('mono-allow-lossy')==='true'}catch{}
const note=text=>{const bar=$('#match-status');bar.hidden=false;$('#match-message').textContent=text;window.OktawkaStreaming?.status(text)};
function cancel(){window.OktawkaStreaming?.status('');generation++;network?.abort();clearTimeout(delayTimer);if(wake)wake();wake=null;$('#match-status').hidden=true;$('#try-lossy').hidden=true;$('#retry-match').hidden=true}
function sleep(ms){return new Promise(resolve=>{wake=resolve;delayTimer=setTimeout(()=>{wake=null;resolve()},ms)})}
function setFallback(enabled){allowLossy=Boolean(enabled);try{localStorage.setItem('mono-allow-lossy',String(allowLossy))}catch{}}
function reconnect(error,track,options){if(error.code!=='DEBRID_AUTH_REQUIRED')return false;note('Connect AllDebrid once to continue this track.');const reconnectGeneration=generation;window.monoConnectAllDebrid(()=>{if(reconnectGeneration!==generation)return;window.monoShowAlbum?.(track.albumId);start(track,options)});return true}
async function search(query,quality,signal){const response=await fetch('/api/cloud-search?quality='+quality+'&q='+encodeURIComponent(query.slice(0,150)),{signal,credentials:'same-origin'});const data=await response.json();if(!response.ok){const error=new Error(data.error||'Music source search is unavailable.');error.code=data.code;throw error}return Array.isArray(data.releases)?data.releases:[]}
async function prepared(release){const id=sourceIds.get(release.hash);const result=await window.monoAllDebridTorrent(id?{id}:{hash:release.hash});if(result.id){sourceIds.set(release.hash,result.id);if(sourceIds.size>50)sourceIds.delete(sourceIds.keys().next().value)}return result}
async function collect(track,quality,signal,current,exclude=new Set()){const candidates=[],pending=[],checked=[],seen=new Set(exclude);let inspected=0;const queries=[track.artist+' '+track.album,track.artist+' '+track.title];for(let qi=0;qi<queries.length&&inspected<3;qi++){if(!current())break;const releases=window.MonoMatch.rankReleases(await search(queries[qi],quality,signal),track,30);if(!current())break;const limit=qi===0?2:3-inspected;let used=0;for(const release of releases){if(seen.has(release.hash)||used>=limit||inspected>=3)continue;seen.add(release.hash);used++;inspected++;let result;try{result=await prepared(release)}catch(e){if(e.code==='DEBRID_AUTH_REQUIRED')throw e;continue}if(!current())return {candidates:[],pending:[]};checked.push({release,result});if(result.pending)pending.push({release,id:result.id,allowLossy:quality==='all'});else candidates.push(...window.MonoMatch.matchFiles(result.files||[],release,track,{allowLossy:quality==='all'}))}if(candidates.length)break}return {candidates:candidates.sort((a,b)=>b.rank-a.rank),pending,checked}}
async function resolve(candidates,current,permitLossy){for(const candidate of candidates){if(!current())return null;try{const result=await window.monoResolveAllDebrid(candidate.link);if(!current())return null;if(result.delayed)continue;const url=new URL(result.link),c=window.MonoMatch.codec(result.filename||candidate.filename);if(url.protocol!=='https:'||url.username||url.password||!c||(!c.lossless&&!permitLossy))continue;return {url:url.href,file:candidate,codec:c}}catch(e){if(e.code==='DEBRID_AUTH_REQUIRED')throw e}}return null}
async function start(track,options={}){cancel();lastTrack=track;lastOptions=options;const permitLossy=options.allowLossy??allowLossy,mine=generation;network=new AbortController();const signal=network.signal,current=()=>mine===generation;audio.pause();$('#cancel-match').textContent='Cancel';note('Finding lossless audio for '+track.title+'…');try{
if(window.OktawkaStreaming?.configured()){const entry=await window.OktawkaStreaming.resolve(track,signal);if(!current())return;window.OktawkaStreaming.status('');tracks.push(entry);render();await play(tracks.length-1,true);if(current()){$('#cancel-match').textContent='Dismiss';$('#match-message').textContent=audio.paused?'Source ready. Press Play to start.':'Playing in Oktawka · '+window.MonoAudioQuality.label(entry)}return}
if(window.monoHasAllDebrid&&!window.monoHasAllDebrid())throw new Error('No playback service connected. Open Streaming quality to connect HiFi without debrid, or choose Radio / Open collection for key-free FLAC.');
let lossless=options.skipLossless?{candidates:[],pending:[],checked:[]}:await collect(track,'lossless',signal,current);if(!current())return;let selected=await resolve(lossless.candidates,current,false),fallback={candidates:[],pending:[]};if(!current())return;
if(!selected&&permitLossy){note('No ready lossless match. Checking lossy fallback for '+track.title+'…');const known=lossless.checked.flatMap(({release,result})=>window.MonoMatch.matchFiles(result.files||[],release,track,{allowLossy:true})).sort((a,b)=>b.rank-a.rank);selected=await resolve(known,current,true);if(!selected){fallback=await collect(track,'all',signal,current,new Set(lossless.checked.map(x=>x.release.hash)));if(!current())return;selected=await resolve(fallback.candidates,current,true)}}
const pending=[...lossless.pending,...fallback.pending];if(!selected&&pending.length){const item=pending[0];for(let count=0;count<12&&current();count++){note('Preparing '+track.title+' in the cloud…');await sleep(5000);if(!current())return;const result=await window.monoAllDebridTorrent({id:item.id});if(!current())return;if(!result.pending){const files=window.MonoMatch.matchFiles(result.files||[],item.release,track,{allowLossy:item.allowLossy});selected=await resolve(files,current,permitLossy);break}}}
if(!selected)throw new Error(permitLossy?'No confident lossless or lossy match was found. Try another release later.':'No confident lossless file matches this song. You can try lossy fallback below.');if(!current())return;
const {file,codec,url}=selected;const entry={title:track.title,artist:track.artist,artistId:track.artistId,album:track.album,albumId:track.albumId,genre:track.genre,duration:track.duration,artwork:track.artwork,url,lossless:false,lossyFallback:!codec.lossless,format:codec.lossless?'Lossless source · bit depth unverified':'Lossy fallback · '+codec.name+' · bitrate unverified',sourceCodec:codec.name,sourceRelease:file.release,catalogId:track.id};let index=tracks.findIndex(t=>t.catalogId===track.id&&t.url===url);if(index<0){tracks.push(entry);index=tracks.length-1}render();await play(index,true);if(!current())return;$('#cancel-match').textContent='Dismiss';note(audio.paused?'Source ready. Press Play in Oktawka if playback did not start.':'Playing '+track.title+' in Oktawka · '+(codec.lossless?'lossless source, bit depth unverified':'lossy fallback ('+codec.name+')'));
}catch(e){if(!current()||e.name==='AbortError')return;if(reconnect(e,track,options))return;$('#cancel-match').textContent='Dismiss';note(e.message||'This track could not be matched.');const searchFailed=String(e.code||'').startsWith('INDEXER_');$('#retry-match').hidden=!searchFailed;$('#try-lossy').hidden=Boolean(permitLossy||searchFailed||window.OktawkaStreaming?.configured())}finally{if(current()){clearTimeout(delayTimer);wake=null}}}
$('#retry-match').onclick=()=>{if(lastTrack)start(lastTrack,lastOptions)};$('#try-lossy').onclick=()=>{setFallback(true);const box=$('#album-lossy');if(box)box.checked=true;if(lastTrack)start(lastTrack,{allowLossy:true,skipLossless:true})};$('#cancel-match').onclick=cancel;window.monoPlayCatalogTrack=start;window.monoCancelCatalogPlayback=cancel;window.monoSetLossyFallback=setFallback;window.monoGetLossyFallback=()=>allowLossy;
})();
